,p_static_id=>'approve'
,p_execution_sequence=>20
,p_outcome=>'APPROVED'
,p_on_event=>'COMPLETE'
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>'sp_approvals.approve ( p_project_approval_chain_id => :V_PROJECT_APPROVAL_CHAIN_ID );'
