,p_process_sequence=>1
,p_process_point=>'ON_NEW_INSTANCE'
,p_process_name=>'set GET_COMMENT_IMAGE_PREFIX (if null)'
,p_static_id=>'set-get-comment-image-prefix-if-null'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if sp_util.get_setting(p_static_id => ''GET_COMMENT_IMAGE_PREFIX'') is null then',
'   sp_util.set_setting (p_static_id     => ''GET_COMMENT_IMAGE_PREFIX'',   ',
'                        p_setting_value => substr(APEX_UTIL.HOST_URL(''SCRIPT''),length(APEX_UTIL.HOST_URL())+1)); ',
