,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--hideHeader js-addHiddenHeadingRoleDesc:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'       f.PROJECT_ID,',
'       max(f.CREATED) last_added,',
'       replace(p.project,'':'','' '') project,',
'       replace(i.initiative,'':'','' '') initiative,',
'       (select ''P''||PRIORITY from SP_PROJECT_PRIORITIES x where x.ID = p.PRIORITY_ID) priority,',
'       p.PCT_COMPLETE,',
'       a.area,',
'       p.FRIENDLY_IDENTIFIER,',
'       p.PROJECT_URL_NAME,',
'       count(*) favorites',
'  from SP_FAVORITES f,',
'       sp_projects p,',
'       SP_TEAM_MEMBERS tm,',
'       sp_initiatives i,',
'       sp_areas a',
'where  f.project_id = p.id and',
'       f.TEAM_MEMBER_ID = tm.id and',
'       p.initiative_id = i.id and',
'       i.area_id = a.id and',
'       nvl(p.ARCHIVED_YN,''N'') = ''N'' and ',
'       p.DUPLICATE_OF_PROJECT_ID is null',
' group by f.project_id, ',
'       p.project, ',
'       i.initiative, ',
'       p.PRIORITY_ID,',
'       p.PCT_COMPLETE,',
'       a.area,',
'       p.FRIENDLY_IDENTIFIER,',
'       p.PROJECT_URL_NAME'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>50
