'  max(decode(x.new_value,:P162_IN_PROGRESS_TO,changed_on)) - min(decode(x.new_value,:P162_IN_PROGRESS_FROM,changed_on)) days',
'from ',
'(',
'  select',
'    pr.id,',
'    pr.project,',
'    pr.status_scale,',
'    pr.created,',
'    pr.pct_complete,',
'    decode(ph.change_type,''CREATE'',10, ph.new_value) new_value,',
