,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'delete from SP_PROJ_INTERACTIONS_LOG ',
' where project_id in (1,2,3,4,5,6);',
'',
'delete from sp_activities',
' where project_id in (1,2,3,4,5,6);',
